import {LANGUAGES,DEFAULT_SETTINGS,LESSON_GROUPS,mapPhysicalKeys} from './data.mjs';
export function createProgress(){return {unlocked:5,letters:{},history:[],lessons:{},lessonHistory:[],tests:[]}}
export function confidence(key,goal){if(!key||!key.samples)return 0;return Math.round(key.lastCPM/goal*(key.correct/Math.max(1,key.correct+key.errors))*100)}
export function targetLetter(progress,lang,goal){let active=[...LANGUAGES[lang].alphabet].slice(0,progress.unlocked);return active.find(c=>!progress.letters[c]||progress.letters[c].samples<5)||active.reduce((a,c)=>confidence(progress.letters[c],goal)<confidence(progress.letters[a],goal)?c:a,active[0])}
export function savePractice(progress,result,lang,goal){for(let [letter,data] of Object.entries(result.keys)){if(!LANGUAGES[lang].alphabet.includes(letter)||!data.avgMs)continue;let k=progress.letters[letter]||{samples:0,correct:0,errors:0,sumMs:0,topCPM:0,lastCPM:0};k.samples++;k.correct+=data.correct;k.errors+=data.errors;k.sumMs+=data.avgMs;k.lastCPM=60000/data.avgMs;k.topCPM=Math.max(k.topCPM,k.lastCPM);progress.letters[letter]=k}progress.history.push({...result,at:Date.now()});if(progress.history.length>1500)progress.history.shift();let alphabet=[...LANGUAGES[lang].alphabet],active=alphabet.slice(0,progress.unlocked);if(progress.unlocked<alphabet.length&&active.every(c=>(progress.letters[c]?.samples||0)>=5&&confidence(progress.letters[c],goal)>=100)){progress.unlocked++;return alphabet[progress.unlocked-1]}return null}
export function dailyProgress(progress,now=new Date()){let start=new Date(now);start.setHours(0,0,0,0);let h=progress.history.filter(r=>r.at>=start.getTime());return{sessions:h.length,minutes:h.reduce((s,r)=>s+r.duration,0)/60000}}
function weighted(items,random){let sum=items.reduce((s,i)=>s+i[1],0),n=random()*sum;for(let i of items){n-=i[1];if(n<=0)return i[0]}return items.at(-1)?.[0]}
export function generateWords({lang='ru',letters=LANGUAGES[lang].alphabet,focus=null,count=25,random=Math.random,punctuation=false}){
 let allowed=new Set(letters),pool=LANGUAGES[lang].words.filter(w=>w.length>=2&&[...w].every(c=>allowed.has(c))&&(!focus||w.includes(focus))),model=new Map();
 for(let w of LANGUAGES[lang].words){let prev='^';for(let c of w){if(allowed.has(c)){let bucket=model.get(prev)||new Map();bucket.set(c,(bucket.get(c)||0)+1);model.set(prev,bucket)}prev=c}}
 let chars=[...allowed];function pseudo(){for(let attempt=0;attempt<24;attempt++){let w='',prev='^',length=3+Math.floor(random()*5);for(let j=0;j<length;j++){let options=[...(model.get(prev)||new Map())].filter(([c])=>allowed.has(c));let c=options.length?weighted(options,random):chars[Math.floor(random()*chars.length)];w+=c;prev=c}if(!focus||w.includes(focus))return w}let w=chars[Math.floor(random()*chars.length)]+(focus||chars[0]);while(w.length<3)w+=chars[Math.floor(random()*chars.length)];return w}
 return Array.from({length:count},(_,i)=>{let w=pool.length&&random()<.72?pool[Math.floor(random()*pool.length)]:pseudo();if(punctuation&&i>0&&i%6===0)w+=i%12===0?'.':',';return w});
}
export function lessonInfo(group,step,layout){let fresh=mapPhysicalKeys(LESSON_GROUPS[group][0],layout);let learned=LESSON_GROUPS.slice(0,group+1).map(([k])=>mapPhysicalKeys(k,layout)).join('');return{fresh,learned,group,step,id:`${layout}:${group}:${step}`}}
export function lessonWords(info,lang,random=Math.random){let chars=[...(info.step===0?info.fresh:info.learned)],count=25;let wordlist=generateWords({lang,letters:chars.join(''),focus:info.fresh[info.step%info.fresh.length],count,random});if(info.step<=2){wordlist=Array.from({length:count},()=>{let n=2+Math.floor(random()*(info.step+2)),s='';for(let j=0;j<n;j++){let use=info.step===0||random()<.65?[...info.fresh]:chars;s+=use[Math.floor(random()*use.length)]}return s})}return wordlist}
export class TypingSession{
 constructor(words,{mode='words',seconds=0,spaceToFinish=true,noWayBack=false,now=()=>performance.now()}={}){this.words=[...words];this.options={mode,seconds,spaceToFinish,noWayBack};this.now=now;this.word=0;this.values=words.map(()=>'');this.positions=words.map(w=>[...w].map(()=>({success:false,error:false,intervals:[]})));this.extras=words.map(()=>new Set());this.status='idle';this.activeMs=0;this.lastStart=0;this.lastKey=null;this.correctRegistrations=0;this.errorRegistrations=0;this.result=null}
 start(){if(this.status==='idle'||this.status==='paused'){this.status='running';this.lastStart=this.now();this.lastKey=null}}
 get duration(){return this.activeMs+(this.status==='running'?Math.max(0,this.now()-this.lastStart):0)}
 pause(){if(this.status==='running'){this.activeMs=this.duration;this.status='paused';this.lastKey=null}}
 resume(){if(this.status==='paused')this.start()}
 get current(){return this.values[this.word]||''}
 get nextChar(){return this.words[this.word]?.[this.current.length]||' '}
 setValue(value){this.tick();if(this.status==='finished')return;if(this.options.noWayBack&&value.length<this.current.length)return;this.start();let prev=this.current,valueString=value.slice(0,this.words[this.word].length+13);let now=this.now();let dt=this.lastKey===null?null:Math.max(1,now-this.lastKey);let added=valueString.length>prev.length;
 for(let i=0;i<valueString.length;i++){if(valueString[i]===prev[i])continue;let expected=this.words[this.word][i],p=this.positions[this.word][i];if(p){if(valueString[i]===expected){if(!p.success){p.success=true;this.correctRegistrations++}}else if(!p.error){p.error=true;this.errorRegistrations++}if(added&&dt!==null&&i===valueString.length-1)p.intervals.push(dt)}else if(!this.extras[this.word].has(i)){this.extras[this.word].add(i);this.errorRegistrations++}}
 this.values[this.word]=valueString;this.lastKey=now;if(!this.options.spaceToFinish&&this.options.mode!=='time'&&this.word===this.words.length-1&&valueString.length>=this.words[this.word].length)this.finish();
 }
 nextWord(){this.tick();if(this.status==='finished'||!this.current.length)return;this.start();if(this.word===this.words.length-1){this.finish();return}this.word++;this.lastKey=this.now()}
 backspace(){if(this.options.noWayBack||this.status==='finished')return;if(this.current.length)this.setValue(this.current.slice(0,-1));else if(this.word>0){this.word--;this.lastKey=this.now()}}
 clearWord(){if(this.options.noWayBack||this.status==='finished')return;if(!this.current.length&&this.word>0)this.word--;this.values[this.word]='';this.lastKey=this.now()}
 tick(){if(this.options.mode==='time'&&this.status==='running'&&this.duration>=this.options.seconds*1000)this.finish()}
 metrics(){let correct=0,incorrect=0,missed=0,extra=0,correctWords=0,incorrectWords=0;let end=this.status==='finished'?Math.min(this.word+1,this.words.length):this.word+1;for(let w=0;w<end;w++){let typed=this.values[w],original=this.words[w];for(let i=0;i<original.length;i++){if(i<typed.length){if(typed[i]===original[i])correct++;else incorrect++}else if(w<this.word||this.status==='finished')missed++}extra+=Math.max(0,typed.length-original.length);if(w<this.word||this.status==='finished'){if(typed===original)correctWords++;else incorrectWords++}}let duration=this.duration,cpm=duration>0?correct/(duration/60000):0;return{cpm,wpm:cpm/5,accuracy:this.correctRegistrations+this.errorRegistrations?this.correctRegistrations/(this.correctRegistrations+this.errorRegistrations)*100:100,duration,correct,incorrect,missed,extra,correctWords,incorrectWords,errors:this.errorRegistrations}}
 finish(){if(this.status==='finished')return this.result;this.activeMs=this.options.mode==='time'?Math.min(this.duration,this.options.seconds*1000):this.duration;this.status='finished';let keys={};let end=this.options.mode==='time'?this.word+1:this.words.length;for(let w=0;w<end;w++){for(let i=0;i<this.positions[w].length;i++){let p=this.positions[w][i];if(!p.success&&!p.error)continue;let letter=this.words[w][i].toLowerCase(),key=keys[letter]||{correct:0,errors:0,intervals:[]};if(p.success)key.correct++;if(p.error)key.errors++;key.intervals.push(...p.intervals);keys[letter]=key}}
 for(let k of Object.values(keys)){k.avgMs=k.intervals.length?k.intervals.reduce((s,n)=>s+n,0)/k.intervals.length:null;delete k.intervals}let misspelled=[];for(let w=0;w<end;w++){let count=this.positions[w].filter(p=>p.error).length+this.extras[w].size;if(this.values[w]!==this.words[w]&&w<this.word)count=Math.max(1,count);if(count)for(let n=0;n<count;n++)misspelled.push(this.words[w])}this.result={...this.metrics(),keys,misspelled,wordCount:this.words.length};return this.result
 }
}
export function loadData(storage){let defaults={version:2,settings:structuredClone(DEFAULT_SETTINGS),progress:{ru:createProgress(),en:createProgress(),fr:createProgress()},legacyLessons:{},guideSeen:false};try{let value=JSON.parse(storage.getItem('ten-fingers-v2')||'null');if(value?.version===2){defaults.settings={...defaults.settings,...value.settings,layouts:{...defaults.settings.layouts,...value.settings?.layouts}};for(let l of ['ru','en','fr'])defaults.progress[l]={...createProgress(),...value.progress?.[l]};defaults.guideSeen=!!value.guideSeen;defaults.legacyLessons=value.legacyLessons||{}}else{defaults.legacyLessons=JSON.parse(storage.getItem('ten-fingers')||'{}')}}catch{}return defaults}
